package main

import (
	"fmt"
)

func main() {
	ch := make(chan int)
	close(ch) // Канал закрыт

	fmt.Println("--- Демонстрация опасного чтения из закрытого канала ---")

	// ОШИБКА: бесконечный цикл for { v := <-ch } сжег бы 100% CPU ядра!
	// Ограничим 5 итерациями для демонстрации
	for i := 0; i < 5; i++ {
		v := <-ch // Мгновенно возвращает 0 без блокировки
		fmt.Printf("Итерация %d: получено zero value = %d\n", i+1, v)
	}

	fmt.Println("\n--- ПРАВИЛЬНОЕ ИСПРАВЛЕНИЕ: проверка comma-ok или for range ---")
	for {
		v, ok := <-ch
		if !ok {
			fmt.Printf("Канал закрыт (ok=false, v=%d). Корректный выход!\n", v)
			break
		}
		_ = v
	}
}

package main

import (
	"fmt"
)

func main() {
	ch1 := make(chan int)
	ch2 := make(chan int)

	// Стадия 1: Генератор
	go func() {
		for i := 1; i <= 3; i++ {
			ch1 <- i
		}
		close(ch1)
	}()

	// Стадия 2: Преобразователь (умножение на 10)
	go func() {
		for val := range ch1 {
			ch2 <- val * 10
		}
		close(ch2)
	}()

	// Стадия 3: Финальный потребитель в main
	fmt.Println("Результаты конвейера (ch1 -> ch2 -> main):")
	for res := range ch2 {
		fmt.Printf(" -> Получено из ch2: %d\n", res)
	}
}

