package main

import (
	"fmt"
	"sync"
)

func Merge(chs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup

	// Для каждого входного канала запускаем воркер пересылки
	for _, ch := range chs {
		wg.Add(1)
		go func(c <-chan int) {
			defer wg.Done()
			for val := range c {
				out <- val
			}
		}(ch)
	}

	// Фоновый контроллер закрытия выходного канала
	go func() {
		wg.Wait()
		close(out)
	}()

	return out
}

func asChan(nums ...int) <-chan int {
	c := make(chan int)
	go func() {
		defer close(c)
		for _, n := range nums {
			c <- n
		}
	}()
	return c
}

func main() {
	ch1 := asChan(1, 2)
	ch2 := asChan(10, 20)
	ch3 := asChan(100, 200)

	merged := Merge(ch1, ch2, ch3)

	fmt.Println("Слияние 3 каналов через Fan-In (Merge):")
	for val := range merged {
		fmt.Printf(" -> %d\n", val)
	}
}

package main

import (
	"fmt"
	"sync"
)

type SafeChannel[T any] struct {
	ch   chan T
	once sync.Once
}

func NewSafeChannel[T any](bufSize int) *SafeChannel[T] {
	return &SafeChannel[T]{
		ch: make(chan T, bufSize),
	}
}

func (s *SafeChannel[T]) Close() {
	s.once.Do(func() {
		close(s.ch)
		fmt.Println("[SafeChannel] Канал успешно закрыт ровно 1 раз!")
	})
}

func main() {
	sc := NewSafeChannel[int](5)

	var wg sync.WaitGroup
	const closers = 3

	// Несколько параллельных горутин пытаются закрыть один и тот же канал
	wg.Add(closers)
	for i := 1; i <= closers; i++ {
		go func(id int) {
			defer wg.Done()
			sc.Close()
		}(i)
	}

	wg.Wait()
	fmt.Println("Все горутины завершили попытки закрытия без паник!")
}

