import (
	"fmt"
)

func FanInSelect(ch1, ch2 <-chan int) <-chan int {
	out := make(chan int)

	go func() {
		defer close(out)

		for ch1 != nil || ch2 != nil {
			select {
			case val, ok := <-ch1:
				if !ok {
					// Отключаем ветку ch1, присваивая nil
					ch1 = nil
					continue
				}
				out <- val
			case val, ok := <-ch2:
				if !ok {
					// Отключаем ветку ch2, присваивая nil
					ch2 = nil
					continue
				}
				out <- val
			}
		}
	}()

	return out
}

func main() {
	in1 := make(chan int)
	in2 := make(chan int)

	go func() {
		in1 <- 10
		in1 <- 20
		close(in1)
	}()

	go func() {
		in2 <- 100
		close(in2)
	}()

	merged := FanInSelect(in1, in2)

	fmt.Println("Результаты Fan-In через select с nil-каналами:")
	for v := range merged {
		fmt.Printf(" -> %d\n", v)
