func fanIn(ch1, ch2 <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for ch1 != nil || ch2 != nil {
			select {
			case v, ok := <-ch1:
				if !ok {
					ch1 = nil
					continue
				}
				out <- v
			case v, ok := <-ch2:
				if !ok {
					ch2 = nil
					continue
				}
				out <- v
			}
		}
	}()
	return out
}

func main() {
	src1 := make(chan int)
	src2 := make(chan int)

	go func() {
		src1 <- 1
		src1 <- 2
		close(src1)
	}()

	go func() {
		src2 <- 10
		src2 <- 20
		close(src2)
	}()

	combined := fanIn(src1, src2)

	fmt.Println("Слияние потоков через fanIn:")
